    1| //! Update mode (owner decision 2026-11-06, Requirement 7.5, design.md §8
    2| //! "Update mode"): `mmhmem update`, and the install command run again on
    3| //! an installed system. Plain questions, so it works in every terminal.
    4| //!
    5| //! **`mmhmem update`** ([`run`], [`session`]): without a terminal nothing
    6| //! is read or changed ([`refuse_without_terminal`]); without an install
    7| //! record it says to run `mmhmem setup` first ([`EXIT_NOT_SET_UP`]). It
    8| //! looks up the newest release (at most [`NEWEST_WAIT`]): unknown → nothing
    9| //! changed, exit 1; not newer → "up to date", exit 0. Otherwise it asks
   10| //! `Update now? [Y/n]` once (Enter = yes; no, or the end of the input,
   11| //! changes nothing and exits with [`EXIT_CANCELLED`], as quitting the menu
   12| //! does) and takes the same verified path as the menu
   13| //! ([`HomeAction::UpdateTo`]: no trusted key → refused; signature and
   14| //! checksum; record updated), then starts the new program as
   15| //! `update --restarted <tag>` and returns its exit code.
   16| //!
   17| //! **Ask only if needed** ([`finish`]): the restarted run plans the
   18| //! recorded choices with its own files. No change → it only checks the
   19| //! tools and prints the results. Changes → it lists them (the review's
   20| //! summaries) and asks `Apply these changes? [Y/n]` once; no keeps the
   21| //! files and says how to review them later (`mmhmem setup`), exit
   22| //! [`EXIT_CANCELLED`].
   23| //!
   24| //! **The install command on an installed system** ([`bootstrap`]): when it
   25| //! brought a newer release than the recorded one, the same question; yes
   26| //! copies the program it already verified (the plan's program change) with
   27| //! the recorded choices, asking only if other files change. An equal or
   28| //! older release opens the normal menu. Without a terminal the install
   29| //! command keeps its standard run (`fallback_default.rs`).
   30| //!
   31| //! Exit codes: the results' code (0 every tool passed or only has steps
   32| //! left that only the user can do, 1 otherwise), 1 when nothing could be
   33| //! done, [`EXIT_CANCELLED`] when the user said no.
   34| 
   35| use std::io::{BufRead, Write};
   36| use std::path::PathBuf;
   37| use std::time::Duration;
   38| 
   39| use super::flow::{Command, EXIT_CANCELLED, Flow, HomeAction, Newest, Next, Resumed, ReviewView};
   40| use super::{EXIT_NEEDS_TERMINAL, Mode, SetupArgs, text};
   41| 
   42| /// The exit code when mmhmem is not set up yet: nothing was changed.
   43| pub const EXIT_NOT_SET_UP: i32 = 1;
   44| 
   45| /// How long `mmhmem update` waits for the newest-release lookup.
   46| pub const NEWEST_WAIT: Duration = Duration::from_secs(15);
   47| 
   48| /// Internal arguments of `mmhmem update`; never shown in `--help`.
   49| #[derive(Debug, Default, Clone, PartialEq, Eq)]
   50| pub struct UpdateArgs {
   51|     /// Local release artefacts (`--release-dir <dir>`), as for setup.
   52|     pub release_dir: Option<PathBuf>,
   53|     /// Started by the previous program right after it updated itself
   54|     /// (`--restarted <tag>`).
   55|     pub restarted: Option<String>,
   56| }
   57| 
   58| impl UpdateArgs {
   59|     /// Parses the arguments after `update`. `Err` holds the unknown argument.
   60|     pub fn parse(args: &[String]) -> Result<Self, String> {
   61|         let setup = SetupArgs::parse(args)?;
   62|         if setup.bootstrap.is_some() {
   63|             return Err("--bootstrap".to_owned());
   64|         }
   65|         Ok(Self {
   66|             release_dir: setup.release_dir,
   67|             restarted: setup.restarted,
   68|         })
   69|     }
   70| 
   71|     fn setup_args(&self) -> SetupArgs {
   72|         SetupArgs {
   73|             bootstrap: None,
   74|             release_dir: self.release_dir.clone(),
   75|             restarted: self.restarted.clone(),
   76|         }
   77|     }
   78| }
   79| 
   80| /// Without a terminal: says to run `mmhmem update` in a terminal window and
   81| /// returns [`EXIT_NEEDS_TERMINAL`]; `None` when the run may go on.
   82| pub fn refuse_without_terminal(mode: Mode, out: &mut dyn Write) -> Option<i32> {
   83|     if mode != Mode::NoTerminal {
   84|         return None;
   85|     }
   86|     let _ = writeln!(out, "{}", text::update::NEEDS_TERMINAL);
   87|     Some(EXIT_NEEDS_TERMINAL)
   88| }
   89| 
   90| /// Entry point of `mmhmem update`. Returns the process exit code.
   91| pub fn run(args: UpdateArgs) -> i32 {
   92|     if let Some(code) = refuse_without_terminal(super::current_mode(), &mut std::io::stdout()) {
   93|         return code;
   94|     }
   95|     let setup = args.setup_args();
   96|     if let Some(code) = super::missing_release_dir(&setup) {
   97|         return code;
   98|     }
   99|     let Some(mut deps) = super::process_deps(&setup) else {
  100|         eprintln!("{}", text::NO_HOME);
  101|         return 1;
  102|     };
  103|     deps.restart.command = Command::Update;
  104|     let mut flow = Flow::load(deps);
  105|     let source = flow.release_source();
  106|     let lookup = move || super::newest_within(source, NEWEST_WAIT);
  107|     let code = session(
  108|         &mut flow,
  109|         lookup,
  110|         &mut std::io::stdin().lock(),
  111|         &mut std::io::stdout().lock(),
  112|     );
  113|     super::restarted(&flow).unwrap_or(code)
  114| }
  115| 
  116| /// The plain questions and answers.
  117| struct Prompt<'a> {
  118|     input: &'a mut dyn BufRead,
  119|     out: &'a mut dyn Write,
  120| }
  121| 
  122| impl Prompt<'_> {
  123|     fn say(&mut self, line: &str) {
  124|         let _ = writeln!(self.out, "{line}");
  125|     }
  126| 
  127|     /// Writes `text` without ending the line.
  128|     fn start(&mut self, text: &str) {
  129|         let _ = write!(self.out, "{text}");
  130|         let _ = self.out.flush();
  131|     }
  132| 
  133|     /// Asks `prompt` until the answer is yes (Enter too) or no; the end of
  134|     /// the input counts as no.
  135|     fn yes(&mut self, prompt: &str) -> bool {
  136|         loop {
  137|             self.start(&format!("{prompt} "));
  138|             let mut line = String::new();
  139|             match self.input.read_line(&mut line) {
  140|                 Ok(0) | Err(_) => {
  141|                     self.say("");
  142|                     return false;
  143|                 }
  144|                 Ok(_) => {}
  145|             }
  146|             match line.trim().to_lowercase().as_str() {
  147|                 "" | "y" | "yes" => return true,
  148|                 "n" | "no" => return false,
  149|                 _ => self.say(text::update::BAD_ANSWER),
  150|             }
  151|         }
  152|     }
  153| }
  154| 
  155| /// `mmhmem update` over `flow` (see the module docs); `lookup` answers the
  156| /// newest release. Returns the exit code; after a verified update the
  157| /// caller starts the new program ([`Flow::restart_now`]).
  158| pub fn session(
  159|     flow: &mut Flow,
  160|     lookup: impl FnOnce() -> Newest,
  161|     input: &mut dyn BufRead,
  162|     out: &mut dyn Write,
  163| ) -> i32 {
  164|     let mut p = Prompt { input, out };
  165|     if let Some(Resumed::Check(tag) | Resumed::Review(tag)) = flow.resume() {
  166|         return finish(flow, &mut p, tag.as_str(), Some(text::update::CHANGES_KEPT));
  167|     }
  168|     if flow.record().is_none() {
  169|         p.say(text::update::NOT_SET_UP);
  170|         return EXIT_NOT_SET_UP;
  171|     }
  172|     p.say(text::update::CHECKING_NEWEST);
  173|     flow.set_newest(lookup());
  174|     let installed = flow.installed_release();
  175|     if *flow.newest() == Newest::Unknown {
  176|         p.say(text::update::NEWEST_UNKNOWN);
  177|         return 1;
  178|     }
  179|     let Some(newest) = flow.newer_release() else {
  180|         p.say(&text::update::up_to_date(installed.as_str()));
  181|         return 0;
  182|     };
  183|     p.say(&text::update::available(
  184|         installed.as_str(),
  185|         newest.as_str(),
  186|     ));
  187|     p.say(text::update::KEEPS_CHOICES);
  188|     if !p.yes(text::update::PROMPT_UPDATE) {
  189|         p.say(text::update::NOTHING_CHANGED);
  190|         return EXIT_CANCELLED;
  191|     }
  192|     if let Some(note) = flow.update_refusal() {
  193|         p.say(note);
  194|         return 1;
  195|     }
  196|     // One progress line (bytes, percent, speed, time left) while the
  197|     // release downloads (bugfix 2026-11-07: a frozen "Downloading…").
  198|     let reporter = crate::setup::download_line::Reporter::stderr(newest.as_str());
  199|     let hook = reporter.hook();
  200|     p.start(&text::update::downloading(newest.as_str()));
  201|     match flow.begin_with(&HomeAction::UpdateTo(newest.clone()), hook) {
  202|         Next::Restart => {
  203|             reporter.finish();
  204|             p.say(&format!(" {}", text::update::VERIFIED));
  205|             0
  206|         }
  207|         // The release is this program's own (or no restart is set up): go
  208|         // on here with the files of this program.
  209|         Next::Review => {
  210|             reporter.finish();
  211|             p.say(&format!(" {}", text::update::VERIFIED));
  212|             finish(
  213|                 flow,
  214|                 &mut p,
  215|                 newest.as_str(),
  216|                 Some(text::update::CHANGES_KEPT),
  217|             )
  218|         }
  219|         Next::Note(note) => {
  220|             reporter.finish();
  221|             p.say("");
  222|             if note == text::UPDATE_FAILED
  223|                 && let Some(reason) = flow.last_note()
  224|             {
  225|                 p.say(reason);
  226|             }
  227|             p.say(note);
  228|             1
  229|         }
  230|         Next::Agents | Next::Progress => 1,
  231|     }
  232| }
  233| 
  234| /// The install command on an installed system brought a newer release:
  235| /// asks once, then installs it with the recorded choices. `None` when this
  236| /// run is not such a run, so the normal menu opens.
  237| pub fn bootstrap(flow: &mut Flow, input: &mut dyn BufRead, out: &mut dyn Write) -> Option<i32> {
  238|     let (recorded, brought) = flow.bootstrap_offer()?;
  239|     let mut p = Prompt { input, out };
  240|     let offer = text::update::bootstrap_available(recorded.as_str(), brought.as_str());
  241|     p.say(&offer);
  242|     p.say(text::update::KEEPS_CHOICES);
  243|     if !p.yes(text::update::PROMPT_UPDATE) {
  244|         p.say(text::update::NOTHING_CHANGED);
  245|         return Some(EXIT_CANCELLED);
  246|     }
  247|     flow.plan_recorded();
  248|     // A no here leaves even the program as it was.
  249|     Some(finish(flow, &mut p, brought.as_str(), None))
  250| }
  251| 
  252| /// Ask only if needed: with nothing to change besides the program, check
  253| /// (and copy the program); otherwise list the changes and ask once.
  254| /// `kept` is said when the user declines (`None`: nothing was changed).
  255| fn finish(flow: &mut Flow, p: &mut Prompt, tag: &str, kept: Option<&str>) -> i32 {
  256|     let view = flow.update_review();
  257|     if view.groups.is_empty() && view.problems.is_empty() {
  258|         p.say(&text::update::updated_checking(tag));
  259|     } else {
  260|         if kept.is_some() {
  261|             p.say(&text::update::updated(tag));
  262|         }
  263|         p.say(text::update::CHANGES_NEEDED);
  264|         changes(p, &view);
  265|         if !p.yes(text::update::PROMPT_APPLY) {
  266|             p.say(kept.unwrap_or(text::update::NOTHING_CHANGED));
  267|             return EXIT_CANCELLED;
  268|         }
  269|         p.say(text::update::MAKING_CHANGES);
  270|     }
  271|     flow.apply_update();
  272|     for line in result_lines(flow) {
  273|         p.say(&line);
  274|     }
  275|     flow.exit_code()
  276| }
  277| 
  278| /// The changes per file and the tools that will be skipped.
  279| fn changes(p: &mut Prompt, view: &ReviewView) {
  280|     for group in &view.groups {
  281|         p.say(&group.file);
  282|         for item in &group.items {
  283|             p.say(&format!("  {} {}", item.mark, item.summary));
  284|         }
  285|     }
  286|     if !view.problems.is_empty() {
  287|         p.say(text::REVIEW_PROBLEMS);
  288|         view.problems.iter().for_each(|l| p.say(l));
  289|     }
  290| }
  291| 
  292| /// The results without the "Checking …" heading said before the check.
  293| fn result_lines(flow: &Flow) -> Vec<String> {
  294|     let mut lines: Vec<String> = flow
  295|         .progress()
  296|         .map(|p| p.all_lines())
  297|         .unwrap_or_default()
  298|         .into_iter()
  299|         .filter(|l| l != text::CHECKING)
  300|         .collect();
  301|     let blank = lines.iter().take_while(|l| l.is_empty()).count();
  302|     lines.drain(..blank);
  303|     if flow.exit_code() == 0 && flow.progress().is_some_and(|p| p.next_steps.is_empty()) {
  304|         lines.push(text::update::DONE.to_owned());
  305|     }
  306|     lines
  307| }
